import 'package:flutter/material.dart';
import 'package:resize/resize.dart';

void main() => runApp(MyApp());

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Resize(
        builder: () {
            return MaterialApp(
                home: Scaffold(
                    body: Container(
                        height: 100.h,
                        width: 100.w,
                    ),
                ),
            );
        },
    );
  }
}
